// Command dealias removes `local := packageVar` statements left behind when a
// regexp literal was hoisted to package scope, rewriting the local's uses to
// name the package var directly.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func main() {
	total := 0
	for _, dir := range os.Args[1:] {
		files, _ := filepath.Glob(filepath.Join(dir, "*.go"))
		sort.Strings(files)
		for _, path := range files {
			if strings.HasSuffix(path, "_test.go") {
				continue
			}
			n, err := run(path)
			if err != nil {
				fmt.Fprintf(os.Stderr, "%s: %v\n", path, err)
				os.Exit(1)
			}
			if n > 0 {
				fmt.Printf("%-24s %d\n", filepath.Base(path), n)
				total += n
			}
		}
	}
	fmt.Printf("TOTAL %d\n", total)
}

func run(path string) (int, error) {
	src, err := os.ReadFile(path)
	if err != nil {
		return 0, err
	}
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, src, parser.ParseComments)
	if err != nil {
		return 0, err
	}
	base := fset.File(file.Pos()).Base()
	off := func(p token.Pos) int { return int(p) - base }

	globals := map[string]bool{}
	for _, decl := range file.Decls {
		gd, ok := decl.(*ast.GenDecl)
		if !ok || gd.Tok != token.VAR {
			continue
		}
		for _, spec := range gd.Specs {
			vs, ok := spec.(*ast.ValueSpec)
			if !ok || len(vs.Names) != len(vs.Values) {
				continue
			}
			for i, name := range vs.Names {
				if isMustCompile(vs.Values[i]) {
					globals[name.Name] = true
				}
			}
		}
	}

	type edit struct {
		start, end int
		text       string
	}
	var edits []edit
	count := 0
	for _, decl := range file.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		for _, stmt := range allStmts(fn.Body) {
			as, ok := stmt.(*ast.AssignStmt)
			if !ok || as.Tok != token.DEFINE || len(as.Lhs) != 1 || len(as.Rhs) != 1 {
				continue
			}
			local, ok := as.Lhs[0].(*ast.Ident)
			if !ok {
				continue
			}
			global, ok := as.Rhs[0].(*ast.Ident)
			if !ok || !globals[global.Name] {
				continue
			}
			// Any other write to the name, including a shadowing `:=` in a nested
			// block, makes the rewrite unsafe.
			if writtenElsewhere(fn, local.Name, as) {
				continue
			}
			count++
			start := off(as.Pos())
			for start > 0 && (src[start-1] == '\t' || src[start-1] == ' ') {
				start--
			}
			end := off(as.End())
			if end < len(src) && src[end] == '\n' {
				end++
			}
			edits = append(edits, edit{start, end, ""})
			ast.Inspect(fn.Body, func(n ast.Node) bool {
				id, ok := n.(*ast.Ident)
				if !ok || id.Name != local.Name || id == local {
					return true
				}
				edits = append(edits, edit{off(id.Pos()), off(id.End()), global.Name})
				return true
			})
		}
	}
	if count == 0 {
		return 0, nil
	}
	sort.SliceStable(edits, func(i, j int) bool { return edits[i].start > edits[j].start })
	out := append([]byte(nil), src...)
	for _, e := range edits {
		out = append(out[:e.start], append([]byte(e.text), out[e.end:]...)...)
	}
	return count, os.WriteFile(path, out, 0o644)
}

func isMustCompile(e ast.Expr) bool {
	call, ok := e.(*ast.CallExpr)
	if !ok {
		return false
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok || sel.Sel.Name != "MustCompile" {
		return false
	}
	pkg, ok := sel.X.(*ast.Ident)
	return ok && pkg.Name == "regexp"
}

func writtenElsewhere(fn *ast.FuncDecl, name string, decl *ast.AssignStmt) bool {
	found := false
	ast.Inspect(fn.Body, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.AssignStmt:
			if s == decl {
				return true
			}
			for _, lhs := range s.Lhs {
				if id, ok := lhs.(*ast.Ident); ok && id.Name == name {
					found = true
				}
			}
		case *ast.UnaryExpr:
			if s.Op == token.AND {
				if id, ok := s.X.(*ast.Ident); ok && id.Name == name {
					found = true
				}
			}
		}
		return true
	})
	return found
}

func allStmts(n ast.Node) []ast.Stmt {
	var out []ast.Stmt
	ast.Inspect(n, func(node ast.Node) bool {
		if s, ok := node.(ast.Stmt); ok {
			out = append(out, s)
		}
		return true
	})
	return out
}
EOF
