// Command scope reports, for one range of statements in a function, which names
// declared outside that range are written inside it.
package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"os"
	"sort"
	"strconv"
)

func main() {
	path, fnName := os.Args[1], os.Args[2]
	lo, _ := strconv.Atoi(os.Args[3])
	hi, _ := strconv.Atoi(os.Args[4])

	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, path, nil, parser.SkipObjectResolution)
	if err != nil {
		panic(err)
	}
	var fn *ast.FuncDecl
	for _, d := range file.Decls {
		if f, ok := d.(*ast.FuncDecl); ok && f.Name.Name == fnName {
			fn = f
		}
	}
	if fn == nil {
		panic("func not found")
	}
	line := func(p token.Pos) int { return fset.Position(p).Line }

	// Names declared inside [lo,hi] are local to the loop body.
	inner := map[string]bool{}
	var target ast.Node
	ast.Inspect(fn, func(n ast.Node) bool {
		if n == nil {
			return false
		}
		if line(n.Pos()) == lo {
			if _, ok := n.(*ast.RangeStmt); ok {
				target = n
			}
		}
		return true
	})
	if target == nil {
		panic("loop not found at line")
	}
	if rs, ok := target.(*ast.RangeStmt); ok {
		for _, e := range []ast.Expr{rs.Key, rs.Value} {
			if id, ok := e.(*ast.Ident); ok {
				inner[id.Name] = true
			}
		}
	}
	ast.Inspect(target, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.AssignStmt:
			if s.Tok == token.DEFINE {
				for _, lhs := range s.Lhs {
					if id, ok := lhs.(*ast.Ident); ok {
						inner[id.Name] = true
					}
				}
			}
		case *ast.DeclStmt:
			if gd, ok := s.Decl.(*ast.GenDecl); ok {
				for _, sp := range gd.Specs {
					if vs, ok := sp.(*ast.ValueSpec); ok {
						for _, nm := range vs.Names {
							inner[nm.Name] = true
						}
					}
				}
			}
		case *ast.RangeStmt:
			for _, e := range []ast.Expr{s.Key, s.Value} {
				if id, ok := e.(*ast.Ident); ok {
					inner[id.Name] = true
				}
			}
		case *ast.FuncLit:
			if s.Type.Params != nil {
				for _, f := range s.Type.Params.List {
					for _, nm := range f.Names {
						inner[nm.Name] = true
					}
				}
			}
		}
		return true
	})

	writes := map[string][]int{}
	root := func(e ast.Expr) *ast.Ident {
		for {
			switch v := e.(type) {
			case *ast.Ident:
				return v
			case *ast.IndexExpr:
				e = v.X
			case *ast.SelectorExpr:
				e = v.X
			case *ast.StarExpr:
				e = v.X
			default:
				return nil
			}
		}
	}
	note := func(e ast.Expr, at token.Pos) {
		if id := root(e); id != nil && !inner[id.Name] {
			writes[id.Name] = append(writes[id.Name], line(at))
		}
	}
	ast.Inspect(target, func(n ast.Node) bool {
		switch s := n.(type) {
		case *ast.AssignStmt:
			for _, lhs := range s.Lhs {
				if id, ok := lhs.(*ast.Ident); ok && s.Tok == token.DEFINE && inner[id.Name] {
					continue
				}
				note(lhs, s.Pos())
			}
		case *ast.IncDecStmt:
			note(s.X, s.Pos())
		}
		return true
	})
	names := make([]string, 0, len(writes))
	for k := range writes {
		names = append(names, k)
	}
	sort.Strings(names)
	fmt.Printf("writes to names declared outside lines %d-%d:\n", lo, hi)
	for _, n := range names {
		fmt.Printf("  %-28s lines %v\n", n, writes[n])
	}
}
EOF
